import raw from "./deployment.json";
import { deploymentSchema, type Deployment } from "./deployment.schema";

export type { DeployedPayToken, DeployedStock, Deployment, ProductParams } from "./deployment.schema";

/**
 * The active deployment: chain, addresses, stocks, pay tokens and product parameters.
 * Generated by `npm run deploy` (or `npm run chain` locally) and committed. Safe on server and client.
 */
export const deployment: Deployment = deploymentSchema.parse(raw);

export const isMainnet = deployment.chainId === 8453;
